template:
{%- macro plural(n, word) -%}{{ n }} {{ word }}{{ "" if n == 1 else "s" }}{%- endmacro -%}
{%- macro item(kind, key) -%}{{ kind }} {{ key[0] }}{% if key|length > 1 and key[1] %} (applies to {{ key[1] }}){% endif %}{%- endmacro -%}
{%- macro fields(row, other) -%}
<dl class="studio-push-fields">
{%- for name, field in row|dictsort %}
<div class="studio-push-field{% if other is none or other.get(name) != field %} studio-push-field-changed{% endif %}"><dt>{{ name }}</dt><dd>{% if field is string %}<pre class="studio-code">{{ field }}</pre>{% else %}<code>{{ field|tojson }}</code>{% endif %}</dd></div>
{%- endfor %}
</dl>
{%- endmacro -%}
{%- set changes = value.changes or [] -%}
{%- set conflicts = value.conflicts or [] -%}
{%- set hidden_changes = value.unreadable_changes or 0 -%}
{%- set hidden_conflicts = value.unreadable_conflicts or 0 -%}
<div class="studio-push-preview" data-studio-push-preview data-studio-source="{{ value.source }}" data-studio-target="{{ value.target }}" data-studio-changes="{{ changes|length }}" data-studio-conflicts="{{ conflicts|length }}" data-studio-unreadable-changes="{{ hidden_changes }}" data-studio-unreadable-conflicts="{{ hidden_conflicts }}">
<p class="studio-push-summary">Pushing {{ value.source }} into {{ value.target }}: {{ plural(changes|length, "change") }}, {{ plural(conflicts|length, "conflict") }}.</p>
{%- if hidden_changes or hidden_conflicts %}
<p class="studio-push-unreadable" data-studio-unreadable>{{ plural(hidden_changes, "change") }} / {{ plural(hidden_conflicts, "conflict") }} on items you can't read</p>
{%- endif %}
{%- if conflicts %}
<h4 class="studio-push-heading">Conflicts</h4>
<ul class="studio-push-conflicts">
{%- for conflict in conflicts %}
<li class="studio-push-conflict">{{ item(conflict.kind, conflict.key) }}: changed on {{ value.target }} since {{ value.source }}'s version was based on it</li>
{%- endfor %}
</ul>
{%- endif %}
{%- if changes %}
<h4 class="studio-push-heading">Changes to {{ value.target }}</h4>
<ol class="studio-push-changes">
{%- for change in changes %}
<li class="studio-push-change" data-studio-change-action="{{ change.action }}">
<h5 class="studio-push-change-title">{{ change.action }} {{ item(change.kind, change.key) }}</h5>
<div class="studio-push-sides">
<section class="studio-push-before"><h6>Before</h6>{% if change.before is none %}<p class="studio-hint">Nothing</p>{% else %}{{ fields(change.before, change.after) }}{% endif %}</section>
<section class="studio-push-after"><h6>After</h6>{% if change.after is none %}<p class="studio-hint">Deleted</p>{% else %}{{ fields(change.after, change.before) }}{% endif %}</section>
</div>
</li>
{%- endfor %}
</ol>
{%- else %}
<p class="studio-hint">No changes you can read.</p>
{%- endif %}
</div>
